int pid_complete(Int_t nEvents = 0, TString prefix = "../data/evtcomplete", Bool_t use_mvd_hvmaps = false)
{
  //-----User Settings:------------------------------------------------------
  TString parAsciiFile = use_mvd_hvmaps ? "all_hvmaps.par" : "all.par";
  //TString input = "psi2s_Jpsi2pi_Jpsi_mumu.dec";
  TString output = "pid";
  TString friend1 = "sim";
  TString friend2 = "reco";
  TString friend3 = "digi";
  TString friend4 = "";
  TString fOptions = "";

  // -----   Initial Settings   --------------------------------------------
  PndMasterRunAna *fRun = new PndMasterRunAna();
  //fRun->SetInput(input);
  fRun->SetInput("dummy");
  fRun->SetOutput(output);
  fRun->AddFriend(friend1);
  fRun->AddFriend(friend2);
  fRun->AddFriend(friend3);
  fRun->AddFriend(friend4);
  fRun->SetParamAsciiFile(parAsciiFile);
  fRun->Setup(prefix);

  FairGeane *Geane = new FairGeane();
  fRun->AddTask(Geane);

  PndPidCorrelator *corr = NULL;
  fRun->AddTask(corr = new PndPidCorrelator());

  corr->SetBackPropagate(kFALSE);

//  if ((!fOptions.Contains("day1")) || (fOptions.Contains("gem"))) {
//    if (fOptions.Contains("filtered")) {
//      corr->SetBarrelTrackBranch("SttMvdGemGenTrack_filtered");
