void PndMasterRunSim::UseEvtGenGenerator(TString EvtGenFile)
{

  TString IniRes = "";

  if (EvtGenFile.Contains(":")) // is the initial resonance provide as <decfile>.dec:iniRes ?
  {
    IniRes = EvtGenFile(EvtGenFile.Index(":") + 1, 1000);
