  if (leplepConfig != "") {
    leplepConfig.ReplaceAll("leplep", "");
    leplepConfig.ReplaceAll(" ", "");
    leplepConfig += ":";

    while (leplepConfig.Contains(":")) {
      TString curpar = leplepConfig(0, leplepConfig.Index(":"));
