      if((strstr(temp, "Decay")) != nullptr)
  {
    fscanf(dec, "%s",particle);
    LOG(info) << "It was found a " << particle << " as initial state." ;
    found = kTRUE;
    break;
  }
    }
  */
  if (IniRes == "")
