  : fRlimit(2.), fRsigma(0.), fDrDz(0.), fDmin(0.), fDmax(0.), fVerbose(0), fDoExtended(false), fDensityFile(""), fDensityGraph(nullptr), fInvertedCDF(nullptr)
{
  // Default constructor
}

